export function fovFor(n,e,o,t,r=!1){if(!(e>0)||e>=o&&!r||e===o)return n;const a=n*Math.PI/360,i=360/Math.PI*Math.atan(Math.tan(a)*(o/e));return Math.min(t,i)}export function poseFor(n,e,o){const t=o.stations[n]||o.stations.desk,r=[...t.eye];if(t.retreat&&e>0&&e<o.view.refAspect){const i=o.view.narrowAspect||.45,s=Math.min(1,(o.view.refAspect-e)/(o.view.refAspect-i)),m=t.eye.map((h,M)=>h-t.aim[M]),p=Math.hypot(...m)||1;for(let h=0;h<3;h++)r[h]+=m[h]/p*t.retreat*s}const a=fovFor(t.fov,e,o.view.refAspect,t.maxFov||o.view.maxFov,!!t.holdWidth);return{eye:r,aim:t.holdTop&&a<t.fov?liftAim(r,t.aim,(t.fov-a)/2):[...t.aim],fov:a}}export function liftAim(n,e,o){const t=e.map((m,p)=>m-n[p]),r=Math.hypot(t[0],t[2]),a=Math.hypot(r,t[1]),i=Math.atan2(t[1],r)+o*Math.PI/180,s=a*Math.cos(i);return[n[0]+t[0]/r*s,n[1]+a*Math.sin(i),n[2]+t[2]/r*s]}export function smoothstep(n){const e=Math.min(1,Math.max(0,n));return e*e*(3-2*e)}const f=(n,e,o)=>n+(e-n)*o;export function blendPose(n,e,o){return{eye:n.eye.map((t,r)=>f(t,e.eye[r],o)),aim:n.aim.map((t,r)=>f(t,e.aim[r],o)),fov:f(n.fov,e.fov,o)}}export function createGlide(n,e,o){let t=0;return{to:e,step(r){t+=Math.max(0,r);const a=o>0?smoothstep(t/o):1;return blendPose(n,e,a)},get done(){return o<=0||t>=o}}}
